<?php

declare(strict_types=1);

require_once __DIR__ . '/Fixtures/IsolatedFinDatabase.php';
require_once __DIR__ . '/DatabaseTestCase.php';
require_once __DIR__ . '/Fixtures/SyntheticStatementGenerator.php';

use PHPUnit\Framework\TestCase;
use Tests\Php\Fixtures\IsolatedFinDatabase;
use Tests\Php\Fixtures\SyntheticStatementGenerator;

/**
 * End-to-end import tests exercising the real import pathway with fully
 * self-owned synthetic fixtures. Every XLSX is generated by
 * SyntheticStatementGenerator from invented data; the canonical
 * `previewStatementImport` / `importStatementEvidence` paths are the
 * same code the production UI calls.
 */
final class StatementImportRealFilesTest extends TestCase
{
    private IsolatedFinDatabase $db;
    private string $tmpDir;

    protected function setUp(): void
    {
        $this->db = IsolatedFinDatabase::create();
        DatabaseTestCase::seedNeutralImportProfiles($this->db->db());
        $this->tmpDir = sys_get_temp_dir() . '/fin-si-' . bin2hex(random_bytes(4));
        mkdir($this->tmpDir);
    }

    protected function tearDown(): void
    {
        if (is_dir($this->tmpDir)) {
            foreach (glob($this->tmpDir . '/*') ?: [] as $f) {
                @unlink($f);
            }
            @rmdir($this->tmpDir);
        }
        $this->db->destroy();
    }

    public function testSyntheticSignedAccountImportsEndToEndWithExplicitAccount(): void
    {
        $accountNumber = 'TEST-SIGNED-' . bin2hex(random_bytes(3));
        $path = SyntheticStatementGenerator::build(
            SyntheticStatementGenerator::FORMAT_SIGNED,
            $this->tmpDir,
            'signed-statement',
            [
                ['booking_date' => '2026-01-10', 'amount' => -100, 'description' => 'Synthetic Test Bank row 1', 'running_balance' => 900],
                ['booking_date' => '2026-01-11', 'amount' => 200, 'description' => 'Synthetic Test Bank row 2', 'running_balance' => 1100],
            ],
            ['account_number' => $accountNumber, 'account_name' => 'Synthetic Test Bank Account']
        );
        $contents = (string)file_get_contents($path);

        // The Account number deliberately does not match the statement's
        // informational identifier. The explicit Account remains authoritative
        // for both Preview and Import.
        $accountId = save_account_definition($this->db->db(), [
            'name' => 'Test Bank Account',
            'account_number' => 'TEST-SIGNED-EXPLICIT-' . bin2hex(random_bytes(3)),
            'currency' => 'CURRENCY',
        ]);

        $preview = preview_statement_import($this->db->db(), $accountId, basename($path), $contents);
        // Stage 5B: provider now carries the profile evidence_namespace.
        self::assertSame('profile:test-bank', (string)$preview['provider']);
        self::assertSame(2, (int)$preview['rows_found']);
        self::assertSame('2026-01-10', (string)$preview['statement_from']);
        self::assertSame('2026-01-11', (string)$preview['statement_to']);
        self::assertSame($accountId, (int)$preview['account']['id']);
        self::assertSame($accountNumber, (string)$preview['file_account_number']);

        $result = $this->runImport($accountId, basename($path), $contents);
        self::assertSame('IMPORTED', (string)($result['outcome'] ?? ''));
        self::assertSame(2, (int)($this->db->db()->query('SELECT COUNT(*) FROM statement_rows')->fetchColumn()));
        $this->assertFinanciallyInert();

        // Statement import is financially inert: running_balance remains evidence only.
        // No observation is created automatically; Balance stays Unknown until the user
        // records one explicitly.
        self::assertNull(account_balance_as_of($this->db->db(), $accountId, '2026-01-10'));
        self::assertNull(account_balance_as_of($this->db->db(), $accountId, '2026-01-11'));
        self::assertSame(0, (int)$this->db->db()->query('SELECT COUNT(*) FROM account_balance_observations')->fetchColumn());
    }

    public function testSyntheticSignedCardImportsEndToEnd(): void
    {
        $accountNumber = 'TEST-CARD-' . bin2hex(random_bytes(3));
        $path = SyntheticStatementGenerator::build(
            SyntheticStatementGenerator::FORMAT_SIGNED_CARD,
            $this->tmpDir,
            'card-statement',
            [
                ['booking_date' => '2026-02-15', 'amount' => -150.5, 'description' => 'Synthetic Test Card row 1', 'running_balance' => 849.5],
            ],
            ['account_number' => $accountNumber, 'account_name' => 'Synthetic Card Account ' . bin2hex(random_bytes(3))]
        );
        $contents = (string)file_get_contents($path);

        $accountId = save_account_definition($this->db->db(), [
            'name' => 'Test Card ' . $accountNumber,
            'account_number' => $accountNumber,
            'type' => 'asset',
            'currency' => 'CURRENCY',
        ]);
        $result = $this->runImport($accountId, basename($path), $contents);
        self::assertSame('IMPORTED', (string)($result['outcome'] ?? ''));
        self::assertSame(1, (int)($this->db->db()->query('SELECT COUNT(*) FROM statement_rows')->fetchColumn()));
        self::assertFinanciallyInert($this->db->db());
    }

