    public function testSyntheticDebitCreditImportsEndToEndWithExplicitAccount(): void
    {
        $accountNumber = bin2hex(random_bytes(8));
        $path = SyntheticStatementGenerator::build(
            SyntheticStatementGenerator::FORMAT_DEBIT_CREDIT,
            $this->tmpDir,
            'debit-credit-statement',
            [
                ['booking_date' => '2026-04-10', 'amount' => -200, 'description' => 'Synthetic Test Bank row 1', 'counterparty' => 'Recipient A', 'direction' => 'Isplata'],
                ['booking_date' => '2026-04-15', 'amount' => 500, 'description' => 'Synthetic Test Bank row 2', 'counterparty' => 'Payer B', 'direction' => 'Uplata'],
            ],
            ['account_number' => $accountNumber, 'sheet_currency' => 'EUR']
        );
        $contents = (string)file_get_contents($path);

        $accountId = save_account_definition($this->db->db(), [
            'name' => 'Test Bank ' . $accountNumber,
            'account_number' => $accountNumber,
            'type' => 'asset',
            'currency' => 'CURRENCY',
        ]);
        $result = $this->runImport($accountId, basename($path), $contents);
        self::assertSame('IMPORTED', (string)($result['outcome'] ?? ''));
        self::assertSame(2, (int)($this->db->db()->query('SELECT COUNT(*) FROM statement_rows')->fetchColumn()));
        self::assertFinanciallyInert($this->db->db());
    }

    public function testExplicitAccountIdIsRequiredForFileDropImport(): void
    {
        $accountNumber = bin2hex(random_bytes(8));
        $path = SyntheticStatementGenerator::build(
            SyntheticStatementGenerator::FORMAT_DEBIT_CREDIT,
            $this->tmpDir,
            'debit-credit-noselection',
            [
                ['booking_date' => '2026-04-10', 'amount' => -10, 'description' => 'Synthetic Test Bank row', 'counterparty' => 'Recipient'],
            ],
            ['account_number' => $accountNumber, 'sheet_currency' => 'EUR']
        );
        $contents = (string)file_get_contents($path);
        // The drop path must stop before parsing when no Account is supplied.
        $result = $this->runImport(null, basename($path), $contents);
        self::assertSame('NEEDS ACCOUNT', (string)($result['outcome'] ?? ''));
        self::assertSame('Select an Account.', (string)($result['reason'] ?? ''));
        self::assertSame(0, (int)$this->db->db()->query('SELECT COUNT(*) FROM statement_imports')->fetchColumn());
        self::assertSame(0, (int)$this->db->db()->query('SELECT COUNT(*) FROM statement_rows')->fetchColumn());
    }

    private function runImport(?int $accountId, string $filename, string $contents): array
    {
        $dropBase = sys_get_temp_dir() . '/fin-si-drop-' . bin2hex(random_bytes(4));
        $importDir = statement_drop_dir($dropBase);
        $importedDir = statement_imported_dir($dropBase);
        @mkdir($importDir, 0700, true);
        @mkdir($importedDir, 0700, true);
        $sourcePath = statement_write_to_drop_inbox($importDir, $filename, $contents);
        try {
            return statement_process_one_dropped_file($this->db->db(), $sourcePath, $importedDir, $accountId);
        } finally {
            @unlink($sourcePath);
            @rmdir($importDir);
            @rmdir($importedDir);
        }
    }

    private function assertFinanciallyInert(): void
    {
        $pdo = $this->db->db();
        self::assertSame(0, (int)$pdo->query('SELECT COUNT(*) FROM transactions')->fetchColumn());
        self::assertSame(0, (int)$pdo->query("SELECT COUNT(*) FROM account_events WHERE event_type<>'opening'")->fetchColumn());
        self::assertSame(0, (int)$pdo->query("SELECT COUNT(*) FROM envelope_movements")->fetchColumn());
        self::assertSame(0, (int)$pdo->query('SELECT COUNT(*) FROM statement_reconciliations')->fetchColumn());
    }
}
